// Pure helpers shared by A (mission) and B (explore). No DOM, no numbers from the design:
// every result is computed from arrays/objects passed in (web/data series, LOLA grid, API payloads).
// Source of truth: this .ts file. mission-calc.js is generated by `npm --prefix web run build:ts`.
import { sealFor } from "../core/data.js";
/**
 * Visibility runs inside the window [i0, i0+n) of a margin array (visible = margin >= 0).
 * → { losses, longest, firstLoss, firstReturn } ; offsets in steps from i0, null when absent.
 * Returns null when the window is outside the array (caller shows "—" + N/D).
 */
export function runs(margin, i0, n) {
    if (!margin || i0 < 0 || n <= 0 || i0 + n > margin.length)
        return null;
    let losses = 0, longest = 0, cur = 0, firstLoss = null, firstReturn = null;
    for (let k = 0; k < n; k++) {
        const v = margin[i0 + k] >= 0;
        const prev = k > 0 ? margin[i0 + k - 1] >= 0 : null;
        if (!v) {
            if (cur === 0)
                losses++;
            cur++;
            if (cur > longest)
                longest = cur;
        }
        else
            cur = 0;
        if (k > 0 && prev && !v && firstLoss == null)
            firstLoss = k;
        if (k > 0 && prev === false && v && firstReturn == null)
            firstReturn = k;
    }
    return { losses, longest, firstLoss, firstReturn };
}
/** Day label index (1-based) of an hour offset, null-safe. */
export const dayOf = (h) => (h == null ? null : Math.floor(h / 24) + 1);
/** Value + unit text; missing → nd ("—"). */
export function fmtVal(v, fmtNum, nd, digits = 0, unit = "") {
    if (v == null || (typeof v === "number" && !Number.isFinite(v)))
        return nd;
    return fmtNum(v, digits) + unit;
}
/** "lat° S · lon° E" with exactly 3 decimals (lon east 0..360). */
export function coordParts(lat, lon) {
    if (!Number.isFinite(lat) || !Number.isFinite(lon))
        return null;
    return { lat: Math.abs(lat), hemi: lat < 0 ? "S" : "N", lonE: ((lon % 360) + 360) % 360 };
}
export function coordText(lat, lon, fmtNum, nd) {
    const c = coordParts(lat, lon);
    if (!c)
        return nd;
    return `${fmtNum(c.lat, 3)}° ${c.hemi} · ${fmtNum(c.lonE, 3)}° E`;
}
/** Parse a typed coordinate: "-89.5, 220" or "89,5 S 220 E". null when not a south-polar point. */
export function parseCoord(text) {
    const s = String(text || "").trim().toUpperCase();
    const m = s.match(/^(-?\d+(?:[.,]\d+)?)\s*°?\s*([NS])?\s*[,;·\s]\s*(-?\d+(?:[.,]\d+)?)\s*°?\s*([EW])?$/);
    if (!m)
        return null;
    let lat = Number(m[1].replace(",", ".")), lon = Number(m[3].replace(",", "."));
    if (m[2] === "S")
        lat = -Math.abs(lat);
    if (m[2] === "N")
        lat = Math.abs(lat);
    if (m[4] === "W")
        lon = -lon;
    if (!(lat >= -90 && lat < 0) || !Number.isFinite(lon))
        return null;
    return { lat, lon };
}
/** Screen pixel → polar stereographic metres, same transform as core/terrain.js. */
export function pxToStereo(px, py, view, W, H) {
    const mpp = view.span / Math.min(W, H);
    return [view.cx + (px - W / 2) * mpp, view.cy - (py - H / 2) * mpp];
}
export function stereoToPx(x, y, view, W, H) {
    const mpp = view.span / Math.min(W, H);
    return [W / 2 + (x - view.cx) / mpp, H / 2 - (y - view.cy) / mpp];
}
/** Index of the LOLA/PGDA cell (row 0 = min y) or -1 outside. */
export function cellIndex(grid, x, y) {
    const i = Math.round((x - grid.x0) / grid.dx), j = Math.round((y - grid.y0) / grid.dx);
    return i >= 0 && j >= 0 && i < grid.nx && j < grid.ny ? j * grid.nx + i : -1;
}
/** PGDA uint8 percent at a point; > 100 or outside → null. */
export function pgdaAt(grid, arr, x, y) {
    const k = cellIndex(grid, x, y);
    if (k < 0 || !arr)
        return null;
    const v = arr[k];
    return v > 100 ? null : v;
}
/**
 * Direction of azimuth az (deg clockwise from local north) drawn on the south-polar map,
 * in screen pixels (y down). Local north points away from the pole.
 */
export function mapDir(lonDeg, azDeg) {
    const l = lonDeg * Math.PI / 180, a = azDeg * Math.PI / 180;
    const north = [Math.sin(l), Math.cos(l)], east = [Math.cos(l), -Math.sin(l)];
    const x = north[0] * Math.cos(a) + east[0] * Math.sin(a), y = north[1] * Math.cos(a) + east[1] * Math.sin(a);
    return [x, -y];
}
/**
 * "Now at site" from GET /api/sites/{id}/sky. The seal follows the payload's science_status
 * (synthetic → SIM; the top seal only for the exact top state). null transition → N/D with the reason.
 */
export function skyNext(resp, body) {
    if (!resp || !resp.ok)
        return { from: "api", seal: "N/D", hours: null, kind: null, reason: resp?.error || null };
    const nt = resp.data?.next_transitions, tr = nt?.[body];
    const seal = sealFor(resp.data?.science_status);
    if (!tr)
        return { from: "api", seal: "N/D", hours: null, kind: null, reason: nt?.[body + "_null_reason"] || null };
    return { from: "api", seal, hours: tr.hours_from_start, kind: tr.kind, at: tr.epoch_utc, resolution: tr.resolution_seconds };
}
/** Horizon profile → SVG polyline points over az 0..360 (x) and elevation (y, up). */
export function horizonPoints(horizon, w, h, elMin, elMax) {
    if (!Array.isArray(horizon) || !horizon.length || !(elMax > elMin))
        return "";
    const y = (el) => h - ((el - elMin) / (elMax - elMin)) * h;
    return horizon.map(p => `${((p.az / 360) * w).toFixed(1)},${y(p.el).toFixed(1)}`).join(" ");
}
export function elRange(horizon, extra = []) {
    const v = [...(horizon || []).map(p => p.el), ...extra.filter(Number.isFinite)];
    if (!v.length)
        return null;
    const lo = Math.min(...v), hi = Math.max(...v), pad = (hi - lo) * 0.15 || 1;
    return [lo - pad, hi + pad];
}
/** Battery margin: declared autonomy (user input, SIM) minus longest night (data). */
export function batteryMargin(autonomyH, longestNightH) {
    if (!Number.isFinite(autonomyH) || autonomyH <= 0 || !Number.isFinite(longestNightH))
        return null;
    return autonomyH - longestNightH;
}
/** Colour ramps for the terrain layers (t in 0..1). */
const lerp = (a, b, t) => a.map((v, i) => Math.round(v + (b[i] - v) * t));
function ramp(stops, t) { t = Math.max(0, Math.min(1, t)); const s = t * (stops.length - 1), i = Math.min(stops.length - 2, Math.floor(s)); return lerp(stops[i], stops[i + 1], s - i); }
export const RAMPS = {
    altitude: [[16, 30, 74], [58, 82, 120], [120, 124, 112], [196, 176, 92], [255, 209, 102]],
    slope: [[40, 20, 70], [120, 60, 160], [200, 90, 170], [250, 150, 190]],
    sun: [[10, 10, 14], [110, 70, 20], [200, 150, 50], [255, 209, 102]],
    earth: [[8, 12, 24], [30, 70, 140], [76, 155, 255], [190, 220, 255]],
};
export const rampColor = (name, t) => ramp(RAMPS[name], t);
export const rampCss = (name) => `linear-gradient(90deg, ${RAMPS[name].map(c => `rgb(${c})`).join(", ")})`;
/** 8-point compass index (0 = N, 1 = NE … 7 = NW) of an azimuth in degrees clockwise from north; null when missing. */
export function compassIndex(azDeg) {
    if (!Number.isFinite(azDeg))
        return null;
    return Math.round((((azDeg % 360) + 360) % 360) / 45) % 8;
}
